"% margin_01: Classical gain and phase margins of a type-1 loop
% L(s) = 1.8 / (s^3 + 3 s^2 + 2 s) = 1.8 / (s (s+1)(s+2))

clear; clc;

num = [1.8];
den = [1.0, 3.0, 2.0, 0.0];

L = tf(num, den);

% [Gm, Pm, Wcg, Wcp] = margin(sys)
%   Gm  : linear gain margin
%   Pm  : phase margin (deg)
%   Wcg : phase-crossover frequency (where phase = -180 deg)
%   Wcp : gain-crossover frequency (where |L| = 1, 0 dB)
[Gm, Pm, Wcg, Wcp] = margin(L);

% Assemble result struct
result = struct();
result.gm_db  = 20 * log10(Gm);   % convert linear gain margin to dB
result.pm_deg = Pm;               % phase margin in degrees
result.w_gc   = Wcp;              % gain crossover frequency (rad/s)
result.w_pc   = Wcg;              % phase crossover frequency (rad/s)

% Write result.json
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
if fid == -1
    error('margin_01:FileOpenFailed', 'Cannot open result.json for writing.');
end
fwrite(fid, jsonStr, 'char');
fclose(fid);

% Console summary (informational)
fprintf('Gain margin      : %.6f (linear), %.6f dB\n', Gm, result.gm_db);
fprintf('Phase margin     : %.6f deg\n', result.pm_deg);
fprintf('Gain crossover   : %.6f rad/s\n', result.w_gc);
fprintf('Phase crossover  : %.6f rad/s\n', result.w_pc);"
